package wirestack.net

import std.sync.*
import std.unittest.*
import std.unittest.testmacro.*
import wirestack as api
import wirestack.internal.transport_stdnet as stdnet

@Test
class NinthNativeOwnershipProbe {
    @TestCase
    func nativeGracefulOwnerIsNotRelabeledWhileItsWrapperReturns(): Unit {
        let listener = stdnet.StdNetTransportListener.bind(ninthProbeEndpoint())
        let accepting = spawn { listener.accept() }
        let native = stdnet.StdNetTransport.connect(listener.localEndpoint)
        let peer = accepting.get(Duration.second)
        let gate = NinthNativeCloseGate(native)
        let stream = TcpStream(gate)
        let closing = spawn { stream.close() }
        try {
            gate.waitUntilNativeClosed()
            match (peer.readSome(api.MutableByteSpan(Array<Byte>(1, repeat: 0u8)),
                context: api.OperationContext(deadline: Some(api.Deadline.after(Duration.second))))) {
                case api.ReadResult.EndOfStream => ()
                case _ => @Fail("native graceful close did not produce peer EOF")
            }
            @Expect(ninthProbeState(stream.state), "Closing")
            stream.abort(reason: Some(api.AbortReason.ApplicationAbort))
            println("NATIVE_GRACEFUL_OWNER_AFTER_ABORT=" + ninthProbeState(stream.state))
            @Expect(ninthProbeState(stream.state), "Closing")
        } finally {
            gate.release()
            closing.get(Duration.second)
            peer.close()
            listener.close()
        }
        println("NATIVE_GRACEFUL_FINAL=" + ninthProbeState(stream.state))
        @Expect(ninthProbeState(stream.state), "Closed")
    }

    @TestCase
    func realTerminalCloseIgnoresStoppedContexts(): Unit {
        let listener = stdnet.StdNetTransportListener.bind(ninthProbeEndpoint())
        let accepting = spawn { listener.accept() }
        let stream = TcpStream.connect(listener.localEndpoint)
        let peer = accepting.get(Duration.second)
        try {
            stream.close()
            let cancellation = api.CancellationSource()
            cancellation.cancel()
            for (context in [api.OperationContext(cancellation: cancellation.token),
                api.OperationContext(deadline: Some(api.Deadline.after(Duration.Zero)))]) {
                var rejected = false
                try {
                    stream.close(context: context)
                } catch (error: Exception) {
                    rejected = true
                    println("TERMINAL_CLOSE_REJECTED=" + error.toString())
                }
                @Expect(!rejected)
                @Expect(ninthProbeState(stream.state), "Closed")
            }
            match (peer.readSome(api.MutableByteSpan(Array<Byte>(1, repeat: 0u8)),
                context: api.OperationContext(deadline: Some(api.Deadline.after(Duration.second))))) {
                case api.ReadResult.EndOfStream => ()
                case _ => @Fail("terminal stream did not close its native peer")
            }
        } finally {
            stream.close()
            peer.close()
            listener.close()
        }
    }
}

private class NinthNativeCloseGate <: stdnet.SocketTransport {
    private let native: stdnet.StdNetTransport
    private let mutex = Mutex()
    private let changed = synchronized(mutex) { mutex.condition() }
    private var nativeClosed = false
    private var released = false

    init(native: stdnet.StdNetTransport) { this.native = native }
    public prop info: api.TransportInfo { get() { native.info } }
    public func readSome(destination: api.MutableByteSpan,
        context!: api.OperationContext = api.OperationContext.background()): api.ReadResult {
        native.readSome(destination, context: context)
    }
    public func writeSome(source: api.ByteSpan,
        context!: api.OperationContext = api.OperationContext.background()): Int64 {
        native.writeSome(source, context: context)
    }
    public func shutdown(direction: api.ShutdownDirection): Unit { native.shutdown(direction) }
    public func close(context: api.OperationContext): Unit {
        native.close(context)
        synchronized(mutex) {
            nativeClosed = true
            changed.notifyAll()
            while (!released) { changed.wait() }
        }
    }
    public func close(): Unit { close(api.OperationContext.background()) }
    public func abort(reason!: ?api.AbortReason = None<api.AbortReason>): Unit {
        native.abort(reason: reason)
    }
    public func isClosed(): Bool { native.isClosed() }
    public func __OWNERSHIP__(): Bool { native.__OWNERSHIP__() }
    func waitUntilNativeClosed(): Unit {
        synchronized(mutex) {
            let deadline = api.Deadline.after(Duration.second)
            while (!nativeClosed) {
                let remaining = deadline.remaining()
                if (remaining <= Duration.Zero) { throw Exception("native close gate timed out") }
                changed.wait(timeout: remaining)
            }
        }
    }
    func release(): Unit { synchronized(mutex) { released = true; changed.notifyAll() } }
}

private func ninthProbeEndpoint(): api.SocketEndpoint {
    api.SocketEndpoint(api.IpAddress(api.IpAddressFamily.Ipv4, [127u8, 0u8, 0u8, 1u8]), 0u16)
}

private func ninthProbeState(state: SocketState): String {
    match (state) {
        case SocketState.Closing => "Closing"
        case SocketState.Closed => "Closed"
        case SocketState.Aborted => "Aborted"
        case _ => "Other"
    }
}
